{
  "name": "opencode-kiro",
  "version": "0.5.2",
  "description": "The ACP-compliant Kiro plugin for opencode: auth via the official kiro-cli login, the live Kiro model lineup through the Agent Client Protocol, and TUI credits display",
  "license": "MIT",
  "author": "Nacho F. Lizaur (https://github.com/NachoFLizaur)",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/NachoFLizaur/opencode-kiro.git"
  },
  "bugs": {
    "url": "https://github.com/NachoFLizaur/opencode-kiro/issues"
  },
  "homepage": "https://github.com/NachoFLizaur/opencode-kiro#readme",
  "type": "module",
  "exports": {
    "./server": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "pretest": "npm run build",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@opentui/solid": "0.5.12",
    "kiro-acp-ai-provider": "3.3.2",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.20",
    "@types/node": "^20.19.42",
    "tsup": "^8.0.0",
    "typescript": "^5.7.0",
    "vitest": "^4.1.8"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "kiro",
    "kiro-cli",
    "acp",
    "agent-client-protocol",
    "amazon-q",
    "aws"
  ]
}
